// Thin adapter. Mapping only — no logic, no branching on the channel beyond
// recording which one it was for the operator.
const out = [];
for (const item of $input.all()) {
  const f = item.json;
  out.push({
    json: {
      product_id: String(f['Product'] ?? '').trim().toLowerCase().replace(/\s+/g, '-'),
      doc_type: f['Document type'],
      raw_text: f['Text'],
      target_prd_id: f['Update an existing PRD (optional)'] || null,
      source_channel: 'form',
    // E4-S6. Collected AT THE DOOR and nowhere else. The wording is deliberately about the
    // person rather than the taxonomy: "first_party" means nothing to someone pasting a
    // document, and a field nobody understands gets answered at random.
    //
    // Anything other than the explicit "I wrote it myself" is third_party. Defaulting the
    // other way would silently weaken every claim this system makes.
      authorship: f['Who wrote this?'] === 'I wrote it myself' ? 'first_party' : 'third_party',
    },
  });
}
return out;

// Thin adapter. Same output shape as the form door.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  out.push({
    json: {
      product_id: b.product_id,
      doc_type: b.doc_type,
      raw_text: b.raw_text,
      title: b.title ?? null,
      received_at: b.received_at ?? null,
      target_prd_id: b.target_prd_id ?? null,
      source_channel: 'webhook',

    // Whether WF1 should run the pipeline it just chose, or stop at the envelope. Default
    // YES: a caller that says nothing wants the work done. `false` exists so the doors can
    // be exercised without paying a model — a check that costs money is a check nobody runs
    // unattended, and a door nobody tests is the door that was shut for two days (BUG-043).
    //
    // It does NOT change the routing decision or suppress the `routed` event. What is
    // recorded about where the document was going is the same either way.
      dispatch: b.dispatch !== false,
    // Optional on the webhook, defaulting to third_party (E4-S6). A caller that says nothing
    // is not claiming to have written the document.
      authorship: b.authorship === 'first_party' ? 'first_party' : 'third_party',
    },
  });
}
return out;

// Non-ok never becomes a silent pass. The reason is machine-readable and travels
// with the trace_id (contracts §1).
for (const item of $input.all()) {
  const p = item.json.payload ?? {};
  console.warn(`[WF1] ingest refused: ${p.reason} missing=${JSON.stringify(p.missing ?? [])}`);
}
return $input.all();
